#include <bits/stdc++.h>
using namespace std;

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;
    vector<double> x(N), y(N);
    for(int i=0;i<N;i++) cin >> x[i] >> y[i];

    vector<bool> is_prime(N, false);
    {
        vector<bool> sieve(max(N,2), true);
        sieve[0] = sieve[1] = false;
        for(int i=2; (long long)i*i < N; i++)
            if(sieve[i])
                for(int j=i*i; j<N; j+=i)
                    sieve[j] = false;
        for(int i=0;i<N;i++) is_prime[i] = sieve[i];
    }

    auto ddist = [&](int a, int b) -> double {
        double dx = x[a]-x[b], dy = y[a]-y[b];
        return sqrt(dx*dx + dy*dy);
    };

    // Start with sorted order: 0,1,2,...,N-1,0
    vector<int> tour(N+1);
    for(int i=0;i<N;i++) tour[i] = i;
    tour[N] = 0;

    // pos[city] = index in tour (for cities 1..N-1, indices 1..N-1)
    vector<int> pos(N);
    for(int i=0;i<N;i++) pos[tour[i]] = i;

    // Penalty positions: step t is penalty if t%10==0, source is tour[t-1]
    // So tour index t-1 where t%10==0 => indices 9,19,29,... need prime cities
    // Try to swap primes into these positions
    // Collect penalty indices and non-prime cities there, and prime cities not at penalty indices

    auto getMultiplier = [&](int t, int src) -> double {
        if(t % 10 == 0 && !is_prime[src]) return 1.1;
        return 1.0;
    };

    // Swap primes into penalty positions greedily (minimize distance increase)
    {
        vector<int> penalty_idx; // tour indices that need primes
        for(int t=10; t<=N; t+=10){
            int idx = t-1; // tour[idx] is the source of step t
            if(idx >= 1 && idx <= N-1)
                if(!is_prime[tour[idx]])
                    penalty_idx.push_back(idx);
        }

        // Find prime cities not at penalty positions
        set<int> penalty_set;
        for(int t=10;t<=N;t+=10) if(t-1>=1 && t-1<=N-1) penalty_set.insert(t-1);

        vector<int> free_primes;
        for(int i=1;i<N;i++){
            if(is_prime[tour[i]] && penalty_set.find(i)==penalty_set.end())
                free_primes.push_back(i);
        }

        // Greedy: for each penalty_idx, find best free_prime to swap with
        for(int pi : penalty_idx){
            if(free_primes.empty()) break;
            int bestJ = -1;
            double bestDelta = 1e18;
            for(int k=0;k<(int)free_primes.size();k++){
                int pj = free_primes[k];
                // Estimate cost change of swapping tour[pi] and tour[pj]
                // Just pick closest by index for speed
                double delta = abs(pi - pj);
                if(delta < bestDelta){ bestDelta=delta; bestJ=k; }
            }
            if(bestJ >= 0){
                int pj = free_primes[bestJ];
                swap(tour[pi], tour[pj]);
                pos[tour[pi]] = pi;
                pos[tour[pj]] = pj;
                free_primes.erase(free_primes.begin()+bestJ);
            }
        }
    }

    // Cost computation
    auto tourCost = [&](const vector<int>& t) -> double {
        double cost = 0;
        for(int s=1;s<=N;s++){
            double d = ddist(t[s-1], t[s]);
            if(s%10==0 && !is_prime[t[s-1]]) d *= 1.1;
            cost += d;
        }
        return cost;
    };

    // Penalty-aware 2-opt with incremental eval, restricted window
    auto startTime = chrono::steady_clock::now();
    auto elapsed = [&]() -> double {
        return chrono::duration<double>(chrono::steady_clock::now()-startTime).count();
    };

    double bestCost = tourCost(tour);
    int maxW = min(N, 200);

    bool improved = true;
    while(improved && elapsed() < 1.7){
        improved = false;
        for(int i=1; i<N-1 && elapsed()<1.7; i++){
            int jmax = min(i+maxW, N-1);
            for(int j=i+1; j<=jmax; j++){
                // Reverse tour[i..j], recompute affected costs
                reverse(tour.begin()+i, tour.begin()+j+1);
                // Recompute cost for steps max(1,i)..min(N,j+1)
                // For speed, compute full delta
                // Actually just recompute full cost for small N, partial for large
                double nc;
                if(N <= 10000){
                    nc = tourCost(tour);
                } else {
                    // Compute partial: steps from i to j+1
                    // But we need full cost... approximate: recompute full
                    nc = tourCost(tour);
                }
                if(nc < bestCost - 1e-10){
                    bestCost = nc;
                    improved = true;
                } else {
                    reverse(tour.begin()+i, tour.begin()+j+1);
                }
            }
        }
        if(N > 5000) break; // Only one pass for large N
    }

    // Or-opt: move single cities, time permitting
    while(elapsed() < 1.85){
        bool imp2 = false;
        for(int i=1;i<N && elapsed()<1.85;i++){
            for(int delta : {-5,-4,-3,-2,-1,1,2,3,4,5}){
                int j = i+delta;
                if(j<1||j>=N||j==i) continue;
                swap(tour[i],tour[j]);
                double nc = tourCost(tour);
                if(nc < bestCost-1e-10){
                    bestCost=nc; imp2=true;
                } else {
                    swap(tour[i],tour[j]);
                }
            }
        }
        if(!imp2) break;
    }

    cout << N+1 << "\n";
    for(int i=0;i<=N;i++) cout << tour[i] << "\n";
}
